using System.Reflection;
using Microsoft.AspNetCore.Mvc.Controllers;
using Microsoft.OpenApi;

namespace Vessel.Web.OpenApi;

/// <summary>
///     API-01: the published REST contract. The document is generated by the built-in ASP.NET Core OpenAPI support from
///     the controllers and is served at <c>/openapi/v1.json</c> to authenticated callers only (session or token).
///     See <c>docs/api/compatibility-policy.md</c>.
/// </summary>
public static class VesselOpenApiExtensions
{
    public const string DocumentName = "v1";
    public const string RoutePattern = "/openapi/{documentName}.json";

    public static IServiceCollection AddVesselOpenApi(this IServiceCollection services)
    {
        services.AddOpenApi(DocumentName, options =>
        {
            // 3.1 rather than the 3.2 default: most generators and API clients do not read 3.2 yet.
            options.OpenApiVersion = OpenApiSpecVersion.OpenApi3_1;
            // Controllers only: Blazor component endpoints, SignalR hubs and health checks are not REST contract.
            options.ShouldInclude = description => description.ActionDescriptor is ControllerActionDescriptor;
            options.AddDocumentTransformer<VesselOpenApiDocumentTransformer>();
            options.AddOperationTransformer<VesselOpenApiOperationTransformer>();
        });

        return services;
    }

    /// <summary>Maps the document endpoint. Anonymous callers are challenged; any authenticated principal may read it.</summary>
    public static IEndpointConventionBuilder MapVesselOpenApi(this IEndpointRouteBuilder endpoints)
    {
        return endpoints.MapOpenApi(RoutePattern).RequireAuthorization();
    }

    internal static string ApiVersion()
    {
        var version = typeof(VesselOpenApiExtensions).Assembly
                          .GetCustomAttribute<AssemblyInformationalVersionAttribute>()?.InformationalVersion
                      ?? typeof(VesselOpenApiExtensions).Assembly.GetName().Version?.ToString()
                      ?? "0.0.0";
        // Drop the source-link commit suffix ("1.2.3+abcdef").
        var plus = version.IndexOf('+', StringComparison.Ordinal);
        return plus > 0 ? version[..plus] : version;
    }
}
